  @AgentMethod({ description: 'Cria uma tarefa pendente e remove espaços nas extremidades do título.', emits: [TaskCreated] })
  static create(id: string, title: string): Task {
    const clean = title.trim();
    if (clean.length === 0) throw new DomainError('TASK_TITLE_REQUIRED', 'Título da tarefa é obrigatório.');
    const task = new Task(id, clean);
    task.record(new TaskCreated({ taskId: id, title: clean }));
    return task;









