      "content": "import { describe, expect, test } from 'bun:test';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';

describe('Task.create', () => {
  for (const bad of ['', '   ', '\t\n']) {
    test(covers(['invariant:Task/titulo-obrigatorio', 'criterion:0001/titulo-invalido'], `rejeita título vazio ${JSON.stringify(bad)}`), () => {
      expect(() => Task.create('t1', bad)).toThrow(expect.objectContaining({ code: 'TASK_TITLE_REQUIRED' }));
    });
  }

  test(covers(['method:Task.create', 'criterion:0001/criacao'], 'cria pendente, normaliza título e registra TaskCreated'), () => {
    const task = Task.create('t1', '  Comprar pão  ');
    expect(task.id).toBe('t1');
    expect(task.title).toBe('Comprar pão');
    expect(task.status).toBe('pending');
    const events = task.pullEvents();
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCreated);
    expect(events[0]!.payload).toEqual({ taskId: 't1', title: 'Comprar pão' });
  });
});
